"use client";

import { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import proj4 from "proj4";
import { ChunkLoader } from "./three/ChunkLoader";
import { createRenderer } from "./three/Renderer";
import { createCamera } from "./three/Camera";
import { createScene } from "./three/Scene";
import { createControls } from "./three/Controls";
import { setupRaycast } from "./three/Raycast";
import { createWeatherLoader } from "./three/WeatherRenderer";

export default function ThreeScene({ settings = {} }) {
  const containerRef = useRef(null);
  const cameraRef = useRef(null);
  const rendererRef = useRef(null);
  const controlsRef = useRef(null);
  const sceneRef = useRef(null);
  const cubeRef = useRef(null);
  const frameRef = useRef(null);
  const loadersRef = useRef(new Map());
  const isLoadingRef = useRef(false);

  const [status, setStatus] = useState({
    buildings: 0,
    roads: 0,
    water: 0,
    weather: 0,
  });

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const envBase = process.env.NEXT_PUBLIC_API_BASE || "http://127.0.0.1:8000";
    const startLon = parseFloat(process.env.NEXT_PUBLIC_STARTLON || "0");
    const startLat = parseFloat(process.env.NEXT_PUBLIC_STARTLAT || "0");
    const [centerX, centerZ] = proj4("EPSG:4326", "EPSG:3857", [startLon, startLat]);

    const renderer = createRenderer(container);
    rendererRef.current = renderer;

    const camera = createCamera(container.clientWidth, container.clientHeight);
    camera.fov = settings.zoom || 60;
    camera.updateProjectionMatrix();
    cameraRef.current = camera;

    const controls = createControls(camera, renderer.domElement);
    controlsRef.current = controls;

    const { scene, cube } = createScene();
    sceneRef.current = scene;
    cubeRef.current = cube;
    scene.background = settings.nightMode ? new THREE.Color(0x0a0a2a) : new THREE.Color(0xbfd9ff);

    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.0;

    const dirLight = new THREE.DirectionalLight(0xffffff, settings.nightMode ? 0.6 : 1.2);
    dirLight.position.set(1000, 2000, 1000);
    scene.add(dirLight);

    const ambLight = new THREE.AmbientLight(0xffffff, settings.nightMode ? 0.15 : 0.35);
    scene.add(ambLight);

    const cleanupRaycast = setupRaycast(renderer.domElement, camera, scene, controls, container);

    camera.position.set(0, 800, 800);
    camera.lookAt(0, 0, 0);
    controls.target.set(0, 0, 0);
    controls.update();

    const getLoader = (layerKey, scene, url) => {
      if (!url) return null;
      return new ChunkLoader(scene, { url, centerOffset: [centerX, centerZ], layerType: layerKey, onProgress: (meta) => {
        setStatus((s) => ({ ...s, [layerKey]: meta.rendered || 0 }));
      }});
    };

    const buildingsLoader = settings.buildings ? getLoader("buildings", scene, `${envBase}/chunk/buildings`) : null;
    const roadsLoader = settings.traffic ? getLoader("roads", scene, `${envBase}/chunk/roads`) : null;
    const waterLoader = settings.terrain ? getLoader("water", scene, `${envBase}/chunk/water`) : null;
    const weatherLoader = settings.weather ? createWeatherLoader(scene, {
      url: `${envBase}/weather/area`,
      centerOffset: [centerX, centerZ],
      minTemp: -20,
      maxTemp: 40,
      minHumidity: 0,
      maxHumidity: 100,
      tileSize: 50,
      elevationAboveGround: 0.2,
      opacity: 0.7,
      mode: "temperature",
      step: 0.05,
      onProgress: (meta) => setStatus((s) => ({ ...s, weather: meta.rendered || 0 })),
    }) : null;

    if (buildingsLoader) loadersRef.current.set("buildings", buildingsLoader);
    if (roadsLoader) loadersRef.current.set("roads", roadsLoader);
    if (waterLoader) loadersRef.current.set("water", waterLoader);
    if (weatherLoader) loadersRef.current.set("weather", weatherLoader);

    const groundGeom = new THREE.PlaneGeometry(500000, 500000, 1, 1);
    const groundMat = new THREE.MeshStandardMaterial({ color: settings.terrain ? 0xf0f0f0 : 0x808080, roughness: 1, metalness: 0 });
    const ground = new THREE.Mesh(groundGeom, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.5;
    ground.receiveShadow = true;
    scene.add(ground);

    const loop = () => {
      if (!cubeRef.current || !sceneRef.current) return;
      cubeRef.current.rotation.y += 0.005;
      dirLight.position.set(camera.position.x, 2000, camera.position.z);
      ground.position.x = camera.position.x;
      ground.position.z = camera.position.z;
      controls.update();

      if (roadsLoader?.meshGroups) {
        for (const group of roadsLoader.meshGroups.values()) {
          group.visible = settings.traffic;
        }
      }

      if (buildingsLoader?.meshGroups) {
        for (const group of buildingsLoader.meshGroups.values()) {
          group.visible = settings.buildings;
        }
      }

      if (weatherLoader?.meshGroups) {
        for (const group of weatherLoader.meshGroups.values()) {
          group.visible = settings.weather;
        }
      }

      renderer.render(scene, camera);
      frameRef.current = requestAnimationFrame(loop);
    };
    loop();

    const handleResize = () => {
      renderer.setSize(container.clientWidth, container.clientHeight);
      camera.aspect = container.clientWidth / container.clientHeight;
      camera.updateProjectionMatrix();
    };
    window.addEventListener("resize", handleResize);
    container.appendChild(renderer.domElement);

    return () => {
      cancelAnimationFrame(frameRef.current);
      try { cleanupRaycast(); } catch (e) {}
      window.removeEventListener("resize", handleResize);
      for (const loader of loadersRef.current.values()) loader.clearAll?.();
      try { renderer.dispose(); } catch (e) {}
      try { cube?.geometry.dispose(); cube?.material.dispose(); } catch (e) {}
      try { groundGeom.dispose(); groundMat.dispose(); } catch (e) {}
    };
  }, [settings]);

  return <div className="w-full h-full relative"><div ref={containerRef} className="w-full h-full" /></div>;
}
